insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MW', 'default', 'Malawi reference chart of accounts', '{}'::jsonb, true, 'companies', array['MW-IFRS-IS', 'MW-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in Malawi. The Institute of Chartered Accountants in Malawi (ICAM), which holds the authority to adopt accounting standards under the Public Accountants and Auditors Act 2012, adopted IFRS in 2001 and IFRS for SMEs for entities that are not publicly accountable. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-based statements below, with the accounts a Malawian company actually keeps — VAT input and output tax, import VAT owed to the Malawi Revenue Authority at the border, withholding tax, PAYE, pension contributions and excise duty payable.', 'ifrs-profile')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

