   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('MW', 'MW-P-17.5', 'Purchase, standard rate 17.5 %, deductible', '{}'::jsonb, 'A local purchase at the general rate, used wholly and necessarily in the business of a taxable person', 'percent', 17.5, 'purchase', 'domestic', date '2025-12-30', null, 'Value Added Tax Act, s. 30(1) — at the end of the tax period a taxable person deducts from output tax the VAT on goods and services bought in Malawi and used wholly, exclusively and necessarily in the course of the business, provided the supply is taxable and the person holds a tax invoice issued under s. 25; s. 30(4) — no deduction twice, and none after twelve months from the date it accrued. Rate: public notice of the Authority, effective 30 December 2025.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'rate-notice-2025', null, null, null, null),
  ('MW', 'MW-P-17.5-ND', 'Purchase, standard rate 17.5 %, input tax not deductible', '{}'::jsonb, 'A purchase whose input tax the Act blocks — entertainment, motor vehicles and their spare parts for a business that does not deal in them', 'percent', 17.5, 'purchase', 'domestic', date '2025-12-30', null, 'Value Added Tax Act, s. 30(5) — no deduction on motor vehicles or their spare parts unless the taxable person deals in or hires them or sells spare parts; s. 30(6) — none on entertainment, including restaurant, meals and hotel expenses, unless the business provides entertainment; s. 30(7) — a supply partly for personal use is deductible only for the business part; s. 30(10) — the Minister may add classes by Order. The tax follows the expense to account 6530. Which purchase falls in these classes is for the preparer to decide.', null, null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MW', 'MW-P-EX', 'Purchase, exempt', '{}'::jsonb, 'A purchase of an exempt supply: no input tax', 'percent', 0, 'purchase', 'exempt', date '2005-01-01', null, 'Value Added Tax Act, s. 20 and the First Schedule — an exempt supply bears no VAT; the buyer has no input tax to deduct.', null, null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MW', 'MW-P-IMP', 'Import of goods, VAT paid at the border', '{}'::jsonb, 'Goods imported: VAT charged on the customs entry at the standard rate', 'percent', 17.5, 'purchase', 'import', date '2025-12-30', null, 'Value Added Tax Act, s. 7(1)(b) and (3) — VAT is charged on every importation of goods, collected under the law on customs duties; s. 8(b) — paid by the importer; s. 28 — the taxable value of imported goods; s. 30(1)(c) — the importer deducts it when holding the customs entry that shows the VAT paid. The VAT is held on the customs control account 2125 until settled.', null, null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MW', 'MW-P-RC-SVC', 'Imported service, VAT accounted for by the receiver', '{}'::jsonb, 'A service received from a supplier outside Malawi: the receiver pays the VAT and deducts it under the ordinary rules', 'percent', 17.5, 'purchase', 'foreign_services_received', date '2025-12-30', null, 'Value Added Tax Act, s. 7(1)(c) — VAT is charged on the supply of any imported service, other than exempt goods and services; s. 8(c) — paid by the receiver of the services; s. 30(1) — input tax is deductible on goods and services imported by the taxable person and used in the business. The pack therefore books the output tax in box 1R and the matching input tax in box 2. Understanding VAT: the person importing the service accounts for the VAT and remits it to the Authority by the 25th of the following month.', null, null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MW', 'MW-P-Z', 'Purchase, zero-rated', '{}'::jsonb, 'A local purchase of a zero-rated good from a taxable supplier', 'percent', 0, 'purchase', 'domestic', date '2005-01-01', null, 'Value Added Tax Act, s. 21 and the Second Schedule — a purchase of a zero-rated supply carries no input tax; it is reported in the zero-rated purchases row.', null, null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MW', 'MW-S-17.5', 'Sale, standard rate 17.5 %', '{}'::jsonb, 'The general rate on a taxable supply made in Malawi, from 30 December 2025', 'percent', 17.5, 'sale', 'domestic', date '2025-12-30', null, 'Value Added Tax Act, s. 7(1)(a) and (2) — Value Added Tax is charged on every supply of goods and services made in Malawi by a taxable person in the course of his business; s. 9 — the rate is applied to the value of the taxable supply (the printed rate in the 2014 consolidation is 16.5 %). The Malawi Revenue Authority''s public notice on the mid-year budget review of 2025/26 increased the rate from 16.5 % to 17.5 % with effect from 30 December 2025. Everything that is neither exempt (First Schedule) nor zero-rated (Second Schedule) is standard-rated (Understanding VAT).', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'rate-notice-2025', null, null, null, null),
  ('MW', 'MW-S-EX', 'Sale, exempt', '{}'::jsonb, 'A supply the First Schedule lists: unprocessed foodstuffs, water, books and newspapers, petroleum, education, banking and life insurance, medical services, residential rentals', 'percent', 0, 'sale', 'exempt', date '2005-01-01', null, 'Value Added Tax Act, s. 20 and the First Schedule — items 1 to 3 live animals, animal products and vegetable products in the raw state; item 4 non-mineral water; item 5 printed books and newspapers; item 6 petroleum oils; item 14 educational services; item 15 banking and life insurance services; item 16 postal services; item 17 funeral services; item 18 medical services; item 19 transport of exports; item 20 rentals and sale of properties used for residential purposes; item 23 betting and gaming. No input tax is deductible on purchases made for exempt supplies (s. 30(3)); a mixed supplier apportions under s. 32. Amendments after 2014 could not be read.', 'E', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MW', 'MW-S-Z-DOM', 'Sale, zero-rated (domestic)', '{}'::jsonb, 'A local supply the Second Schedule taxes at nil: fertilizers, pharmaceutical products, exercise books, salt, laundry soap, mosquito nets and others', 'percent', 0, 'sale', 'domestic', date '2005-01-01', null, 'Value Added Tax Act, s. 21 and the Second Schedule as printed in the 2014 consolidation: fertilizers (tariff headings 3101 to 3105), condoms, exercise books, laundry soap, salt, pharmaceutical products (3001 to 3006), mosquito and sandfly nets and the other items listed, a number of which were deleted by Act No. 23 of 2011. Amendments after 2014 could not be read: the list in force has to be checked against the current Schedule before a supply is coded here.', 'Z', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MW', 'MW-S-Z-EXP', 'Sale, zero-rated (export)', '{}'::jsonb, 'A supply of goods or services exported from Malawi', 'percent', 0, 'sale', 'export', date '2005-01-01', null, 'Value Added Tax Act, s. 21 and the Second Schedule, item 1 — output tax is nil on the export of goods and services; item 2 — goods shipped as stores on aircraft and vessels leaving Malawi. A zero-rated supply is a taxable supply, so the input tax of its maker stays deductible (s. 30(1)). The evidence an exporter must hold is in the Authority''s guidance, which this pack could not open; the Authority''s 2026/27 notice on sugar exports mentions refund on proof of export and of repatriation of the proceeds.', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
