insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MW', 'MW-VAT-RETURN', 'Monthly Value Added Tax return', array['month']::declaration_period[], 'month'::declaration_period, date '2005-01-01', null, 'Value Added Tax Act, s. 34(1) and (2) — a taxable person accounts for VAT each calendar month on a return in the prescribed form, which states the VAT payable for the period, the input tax credit or refund claimed and such other matters as are prescribed. The prescribed form and its boxes could not be opened from the machine this pack was written on (the Authority''s site is a script-driven application and its forms library asks for a login): the rows below are this pack''s own, named after the operations of the Act, and the gap is recorded in this pack''s README. Box numbers do not claim to be the numbers of the Authority''s form.', true,'day_of_month_after_period'::filing_deadline_rule, 25, null, 'Value Added Tax Act, s. 34(4) and (6) — the return is submitted, and the VAT due paid, not later than the twenty-fifth day of the month immediately following the month to which the return relates; the Authority''s Understanding VAT brochure says the same. s. 34(5): the Commissioner General may extend the period on application. Penalty for a late return in the 2014 text: K20,000 and K1,000 a day (not modelled).', 'vat-act', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('MW', 'MW-VAT-RETURN', 'ZE', 'base', 'Zero-rated supplies — exports', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 21 and Second Schedule, item 1 — the value of exports of goods and services taxed at nil. A reporting row of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', 'ZL', 'base', 'Zero-rated supplies — local', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 21 and the Second Schedule — the value of local supplies taxed at nil (fertilizers, pharmaceutical products and the other items). A reporting row of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', 'EX', 'base', 'Exempt supplies', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 20 and the First Schedule — the value of exempt supplies. A reporting row of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '1S', 'base', 'Standard-rated supplies — value', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, ss. 7 and 9 — the value of the standard-rated supplies on which output VAT is charged, net of credit notes; and the output VAT itself. Rows of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '1S', 'tax', 'Output VAT on standard-rated supplies', '{}'::jsonb, 45, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, ss. 7 and 9 — the value of the standard-rated supplies on which output VAT is charged, net of credit notes; and the output VAT itself. Rows of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '1R', 'base', 'Imported services — value', '{}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, ss. 7(1)(c) and 8(c) — the value of services received from outside Malawi and the VAT the receiver pays on them, included in output VAT. Rows of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '1R', 'tax', 'Output VAT on imported services', '{}'::jsonb, 55, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, ss. 7(1)(c) and 8(c) — the value of services received from outside Malawi and the VAT the receiver pays on them, included in output VAT. Rows of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '1', 'total', 'Output VAT (total)', '{}'::jsonb, 60, null, array['1S:tax', '1R:tax']::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 34(2)(a) — the VAT payable for the period before the input tax credit: output VAT on standard-rated supplies plus the VAT the receiver pays on imported services. A total of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', 'ZP', 'base', 'Zero-rated purchases — value', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 21 — the value of local purchases taxed at nil. A reporting row of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '2', 'base', 'Standard-rated local purchases — value', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 30(1) — the purchases on which input tax is incurred and the input tax deducted on local purchases and on imported services, net of credits received. Rows of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '2', 'tax', 'Input VAT on local purchases and imported services', '{}'::jsonb, 85, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 30(1) — the purchases on which input tax is incurred and the input tax deducted on local purchases and on imported services, net of credits received. Rows of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '3', 'base', 'Imports of goods — value', '{}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, ss. 7(1)(b) and 30(1)(c) — the value of imported goods and the VAT paid on the customs entry, deducted by the importer. Rows of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '3', 'tax', 'Input VAT on imports', '{}'::jsonb, 95, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, ss. 7(1)(b) and 30(1)(c) — the value of imported goods and the VAT paid on the customs entry, deducted by the importer. Rows of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '4', 'total', 'Total input VAT', '{}'::jsonb, 100, null, array['2:tax', '3:tax']::text[], '{}'::text[], null, null, false, false, null, 'Value Added Tax Act, s. 30 — the total input tax credit claimed: local purchases and imported services (row 2) plus imports (row 3). A total of this pack.', 'vat-act'),
  ('MW', 'MW-VAT-RETURN', '5', 'total', 'VAT payable or repayable', '{}'::jsonb, 110, null, array['1']::text[], array['4']::text[], null, null, false, false, null, 'Value Added Tax Act, ss. 31 and 34(2) — output VAT minus the input tax credit. A positive figure is payable by the 25th of the following month; a negative figure is excess input tax carried forward or refunded under s. 31. A total of this pack.', 'vat-act')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  sequence        = excluded.sequence,
  print_sequence  = excluded.print_sequence,
  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
