  source_key      = excluded.source_key;

insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key, result_in_progress, result_in_progress_name, result_in_progress_name_i18n)
values
  ('MW-IFRS-IS', 'MW', 'default', 'Statement of profit or loss', 'income_statement', 'IFRS-SME', date '2005-01-01', null, 'Malawi has no statutory layout for the statements of a company. The Institute of Chartered Accountants in Malawi (ICAM), which holds the authority to adopt accounting standards under the Public Accountants and Auditors Act 2012, adopted IFRS in 2001 and IFRS for SMEs for entities that are not publicly accountable, so the pack presents the position and the result in the order of IFRS for SMEs (sections 4 and 5). The grouping of accounts into lines is this pack''s; the IFRS Foundation''s jurisdiction profile of 2016 is the source of the framework and has to be confirmed against the current ICAM position.', 'ifrs-profile', null, null, '{}'::jsonb),
  ('MW-IFRS-SFP', 'MW', 'default', 'Statement of financial position', 'balance_sheet', 'IFRS-SME', date '2005-01-01', null, 'Malawi has no statutory layout for the statements of a company. The Institute of Chartered Accountants in Malawi (ICAM), which holds the authority to adopt accounting standards under the Public Accountants and Auditors Act 2012, adopted IFRS in 2001 and IFRS for SMEs for entities that are not publicly accountable, so the pack presents the position and the result in the order of IFRS for SMEs (sections 4 and 5). The grouping of accounts into lines is this pack''s; the IFRS Foundation''s jurisdiction profile of 2016 is the source of the framework and has to be confirmed against the current ICAM position.', 'ifrs-profile', 'combined', 'Result of the current financial year', '{}'::jsonb)
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key,
  result_in_progress           = excluded.result_in_progress,
  result_in_progress_name      = excluded.result_in_progress_name,
  result_in_progress_name_i18n = excluded.result_in_progress_name_i18n;

