update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Value Added Tax Act, s. 25(1) and (2) — a taxable person issues an electronic fiscal device generated tax invoice, or a tax invoice in the prescribed form, and keeps a copy in serial number order; s. 30(1)(b) — input tax on a local purchase is deductible only against a tax invoice issued under s. 25. Malawian law asks for a serial number and not for a series with no gap, which is why `numbering` is `sequential`.',
  numbering_source_key          = 'vat-act',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Value Added Tax Act, s. 24 — the time of supply. The section was read in the 2014 consolidation only; it names a time of supply by delivery, invoice and payment, and Ekwo''s closed vocabulary expresses `earliest_of_delivery_or_payment`, the nearest value. The wording of the section has to be confirmed against the current Act.',
  tax_point_source_key          = 'vat-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'No Malawian text this pack could open obliges a business to exchange a structured electronic invoice with another business in the sense Ekwo''s vocabulary gives the word: there is no Peppol authority, no published profile and no scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`. What Malawi has is a clearance system run by the Malawi Revenue Authority: s. 25 of the Value Added Tax Act (2014 consolidation) requires an electronic fiscal device generated tax invoice or a prescribed tax invoice, and the Authority runs an Electronic Invoicing System (EIS) with a point-of-sale management portal that replaces electronic fiscal devices. The Authority''s own notices on the EIS (start date, who must use it, penalties) could not be opened; trade commentary reports a transition ending on 31 January 2026 and mandatory use from 1 May 2026, which this pack does not rely on. That is real-time clearance with the tax administration and not a peer-to-peer exchange; the gap is recorded in docs/international.md and in this pack''s README, and the socle is not patched to fit it.',
  einvoice_source_key           = 'eis-portal',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'MW';
